      [
        "While I was gone - and I - too late -",
        "mientras yo estuviera ausente — y yo — demasiado tarde —"
      ],
      [
        "Should reach the Heart that wanted me -",
        "llegara al corazón que me necesitaba —"
      ],
      [
        "If I should disappoint the eyes",
        "si defraudara a los ojos"
      ],
      [
        "That hunted - hunted so - to see -",
        "que buscaban — buscaban tanto — verme —"
      ],
      [
        "And could not bear to shut until",
        "y no soportaban cerrarse hasta"
      ],
      [
        "They 'noticed' me - they noticed me -",
        "que me «vieran» — que me vieran —"
      ],
      [
        "If I should stab the patient faith",
        "si hiriera la fe paciente"
      ],
      [
        "So sure I'd come - so sure I'd come -",
        "tan segura de que vendría — tan segura de que vendría —"
      ],
      [
        "It listening - listening - went to sleep -",
        "que, escuchando — escuchando — se durmió —"
      ],
      [
        "Telling my tardy name -",
        "pronunciando mi nombre tardío —"
      ],
      [
        "My Heart would wish it broke before -",
        "mi corazón desearía haberse roto antes —"
      ],
      [
        "Since breaking then - since breaking then -",
        "pues romperse entonces — romperse entonces —"
      ],
      [
        "Were useless as next morning's sun -",
        "sería tan inútil como el sol de la mañana siguiente —"
      ],
      [
        "Where midnight frosts - had lain!",
        "¡donde habían caído las heladas de medianoche!"
      ]
